// STUB — Phase 8 Skeleton
// PURPOSE: Load Brand Brain data for Vị Cuốn
// PRODUCTION: Read from brand-brain/vi-cuon.md via filesystem, Google Sheets, or Supabase
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL
// CONSTRAINT: No real credential in skeleton.

const inputData = $input.first().json;

const brandBrain = {
  brand_name: inputData.brand_name || 'Vị Cuốn',
  brand_positioning: 'REPLACE_WITH_BRAND_POSITIONING',
  target_customer: 'REPLACE_WITH_TARGET_CUSTOMER',
  menu_items: 'REPLACE_WITH_MENU_ITEMS',
  price_range: 'REPLACE_WITH_PRICE_RANGE',
  address: 'REPLACE_WITH_ADDRESS',
  opening_hours: 'REPLACE_WITH_OPENING_HOURS',
  key_offers: 'REPLACE_WITH_KEY_OFFERS',
  tone_of_voice: 'REPLACE_WITH_TONE_OF_VOICE',
  forbidden_claims: 'REPLACE_WITH_FORBIDDEN_CLAIMS',
  approval_status: 'REPLACE_WITH_APPROVAL_STATUS'
};

return [{ json: { ...inputData, brandBrain, brandBrainLoaded: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Call AI model to generate ads pack draft
// PRODUCTION: HTTP Request to Claude API (claude-sonnet-4-6) or equivalent LLM
// CREDENTIAL NEEDED: REPLACE_WITH_ANTHROPIC_API_KEY
// CONSTRAINT: No real API call in skeleton. Returns mock ads pack object.
// SCHEMA: Output must conform to schemas/ads-pack.schema.json
// CRITICAL: No ads spend committed at this step — draft only
// COMPLIANCE: compliance_notes field must always be populated

const inputData = $input.first().json;

// Mock ads pack — all required fields from ads-pack.schema.json
const adsPack = {
  ads_pack_id: 'AP-VQ-STUB-001',
  brand_id: inputData.brand_id || 'VQ',
  brand_name: inputData.brand_name || 'Vị Cuốn',
  campaign_objective: inputData.campaign_objective || 'Awareness',
  platform: inputData.platform || 'Facebook Ads',
  funnel_stage: inputData.funnel_stage || 'Top of Funnel (TOF)',
  target_audience: inputData.target_audience || 'REPLACE_WITH_TARGET_AUDIENCE',
  angle: 'STUB_ANGLE — Replace with AI-generated creative angle and positioning hook',
  primary_text: 'STUB_PRIMARY_TEXT — Replace with AI-generated main ad body copy',
  headline: 'STUB_HEADLINE — Replace with AI-generated short headline',
  description: null,
  cta: 'Learn More',
  creative_brief_ref: null,
  offer: inputData.offer || '[OWNER_TO_PROVIDE_OFFER]',
  compliance_notes: 'STUB: No health claims. No fake scarcity. No unverified pricing. Owner to confirm offer before use.',
  approval_status: 'Draft',
  created_by_agent: 'n8n-ads-pack-auto (STUB)',
  created_at: new Date().toISOString(),
  notes: 'Phase 8 skeleton stub. No real AI call made. No ads spend committed.'
};

return [{ json: { ...inputData, adsPack, aiCallCompleted: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Validate ads pack against ads-pack.schema.json required fields
// SCHEMA REF: schemas/ads-pack.schema.json
// REQUIRED: ads_pack_id, brand_id, brand_name, campaign_objective, platform,
//   funnel_stage, target_audience, angle, primary_text, headline, cta,
//   approval_status, created_by_agent, created_at
// COMPLIANCE CHECK: compliance_notes must be present

const inputData = $input.first().json;
const pack = inputData.adsPack || {};

const requiredFields = [
  'ads_pack_id', 'brand_id', 'brand_name', 'campaign_objective',
  'platform', 'funnel_stage', 'target_audience', 'angle',
  'primary_text', 'headline', 'cta', 'approval_status',
  'created_by_agent', 'created_at'
];

const missingFields = requiredFields.filter(f => !pack[f] || pack[f] === '');
// Compliance check
if (!pack.compliance_notes) missingFields.push('compliance_notes');

const validationPass = missingFields.length === 0;
const validationErrors = missingFields.map(f => `SCHEMA_VALIDATION_FAIL: Missing required field: ${f}`);

return [{ json: { ...inputData, validation_pass: validationPass, validation_errors: validationErrors } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Write structured log entry per schemas/log-entry.schema.json
// PRODUCTION: Append row to Google Sheets log tab or Supabase logs table
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;
const pack = inputData.adsPack || {};

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-STUB-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-ads-pack-auto (STUB)',
  action_type: 'Ads Pack Draft',
  input_ref: inputData.campaign_objective || 'STUB_INPUT',
  output_ref: pack.ads_pack_id || 'STUB_OUTPUT',
  status: 'Success',
  summary: 'Ads Pack Auto skeleton executed. Draft created with approval_status=Draft. No ads spend. No real AI call.',
  errors: (inputData.validation_errors && inputData.validation_errors.length) ? inputData.validation_errors : null,
  next_action: 'Send ads pack to approval queue. Owner to review compliance_notes and set approval_status=Approved before any ads launch.',
  owner_action_required: false
};

return [{ json: { ...inputData, logEntry, logWritten: true } }];
